CREATE TABLE media_account_write_gates(account_id uuid PRIMARY KEY,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),erased_at timestamptz(3),request_id uuid,CHECK((erased_at IS NULL)=(request_id IS NULL)),CHECK(created_at<=updated_at));
CREATE TABLE media_objects(
 id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES media_account_write_gates(account_id),client_post_id uuid NOT NULL,purpose text NOT NULL CHECK(purpose='post_attachment'),
 status text NOT NULL DEFAULT 'awaiting_upload' CHECK(status IN('awaiting_upload','verifying','ready','rejected','revoked','deleted')),
 declared_mime text NOT NULL CHECK(declared_mime IN('image/jpeg','image/png','image/webp')),declared_bytes integer NOT NULL CHECK(declared_bytes BETWEEN 1 AND 10485760),input_sha256 text NOT NULL CHECK(input_sha256 ~ '^[a-f0-9]{64}$'),
 mime_type text CHECK(mime_type IS NULL OR mime_type='image/webp'),byte_size integer CHECK(byte_size BETWEEN 1 AND 1048576),sha256 text CHECK(sha256 ~ '^[a-f0-9]{64}$'),width integer CHECK(width BETWEEN 1 AND 2048),height integer CHECK(height BETWEEN 1 AND 2048),object_key text UNIQUE,
 version integer NOT NULL DEFAULT 1 CHECK(version>0),authorization_version integer NOT NULL DEFAULT 1 CHECK(authorization_version>0),account_access_version integer NOT NULL CHECK(account_access_version>0),storage_authorization_version integer NOT NULL CHECK(storage_authorization_version>0),photo_authorization_version integer NOT NULL CHECK(photo_authorization_version>0),failure_code text,
 created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),verified_at timestamptz(3),revoked_at timestamptz(3),deleted_at timestamptz(3),
 UNIQUE(account_id,id),UNIQUE(account_id,id,client_post_id),CHECK(created_at<=updated_at),CHECK(status<>'ready' OR (mime_type IS NOT NULL AND byte_size IS NOT NULL AND sha256 IS NOT NULL AND width IS NOT NULL AND height IS NOT NULL AND object_key IS NOT NULL AND verified_at IS NOT NULL)),CHECK(status NOT IN('revoked','deleted') OR revoked_at IS NOT NULL),CHECK(status<>'deleted' OR deleted_at IS NOT NULL));
CREATE INDEX media_objects_account ON media_objects(account_id,created_at,id);
CREATE TABLE media_upload_slots(id uuid PRIMARY KEY,account_id uuid NOT NULL,media_id uuid NOT NULL,staging_key text NOT NULL UNIQUE,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','uploading','uploaded','completed','replaced','expired','revoked')),version integer NOT NULL DEFAULT 1 CHECK(version>0),upload_key uuid,attempt_id uuid,lease_until timestamptz(3),expires_at timestamptz(3) NOT NULL,created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),ended_at timestamptz(3),uploaded_at timestamptz(3),FOREIGN KEY(account_id,media_id) REFERENCES media_objects(account_id,id),UNIQUE(account_id,media_id,id),CHECK((state='uploading')=(attempt_id IS NOT NULL AND lease_until IS NOT NULL)),CHECK(expires_at>created_at),CHECK((state IN('completed','replaced','expired','revoked'))=(ended_at IS NOT NULL)),CHECK(state<>'uploaded' OR uploaded_at IS NOT NULL));
CREATE UNIQUE INDEX media_current_upload_slot ON media_upload_slots(account_id,media_id) WHERE state IN('active','uploading','uploaded');
CREATE TABLE media_use_grants(account_id uuid NOT NULL,media_id uuid NOT NULL,client_post_id uuid NOT NULL,post_id uuid NOT NULL,position smallint NOT NULL CHECK(position BETWEEN 1 AND 9),media_version integer NOT NULL CHECK(media_version>0),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','revoked')),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),confirmed_at timestamptz(3),revoked_at timestamptz(3),PRIMARY KEY(account_id,media_id),FOREIGN KEY(account_id,media_id,client_post_id) REFERENCES media_objects(account_id,id,client_post_id),UNIQUE(account_id,post_id,position),CHECK((state='revoked')=(revoked_at IS NOT NULL)));
CREATE INDEX media_grants_post ON media_use_grants(account_id,post_id);
CREATE TABLE media_jobs(id uuid PRIMARY KEY,account_id uuid NOT NULL,media_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('verify','purge')),media_version integer NOT NULL CHECK(media_version>0),state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','succeeded','failed','blocked')),version integer NOT NULL DEFAULT 1 CHECK(version>0),attempt_id uuid,attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0 AND (kind='purge' OR attempt_count<=5)),lease_until timestamptz(3),retry_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),output_key text UNIQUE,failure_code text,created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),started_at timestamptz(3),finished_at timestamptz(3),FOREIGN KEY(account_id,media_id) REFERENCES media_objects(account_id,id),UNIQUE(account_id,media_id,kind),CHECK((state='running')=(attempt_id IS NOT NULL AND lease_until IS NOT NULL)),CHECK(state NOT IN('succeeded','blocked') OR finished_at IS NOT NULL),CHECK(created_at<=updated_at));
CREATE INDEX media_jobs_dispatch ON media_jobs(state,retry_at,created_at);
ALTER TABLE media_jobs ADD COLUMN output_keys text[] NOT NULL DEFAULT '{}';
CREATE TABLE media_commands(account_id uuid NOT NULL REFERENCES media_account_write_gates(account_id),operation text NOT NULL CHECK(operation IN('create','slot','complete','delete')),idempotency_key uuid NOT NULL,target_id uuid NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_id,operation,idempotency_key));
CREATE TABLE media_erase_receipts(account_id uuid PRIMARY KEY REFERENCES media_account_write_gates(account_id),request_id uuid NOT NULL UNIQUE,state text NOT NULL CHECK(state IN('preparing','completed')),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz(3),CHECK((state='completed')=(completed_at IS NOT NULL)));
CREATE FUNCTION media_enforce_write_gate() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE fenced timestamptz;blocked boolean;BEGIN
 IF TG_OP='UPDATE' AND NEW.account_id<>OLD.account_id THEN RAISE EXCEPTION 'immutable media account' USING ERRCODE='42501';END IF;
 SELECT erased_at INTO fenced FROM media_account_write_gates WHERE account_id=NEW.account_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'missing media account gate' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='media_objects' THEN blocked:=NEW.status NOT IN('revoked','deleted');ELSIF TG_TABLE_NAME='media_upload_slots' THEN blocked:=NEW.state NOT IN('replaced','expired','revoked');ELSIF TG_TABLE_NAME='media_use_grants' THEN blocked:=NEW.state='active';ELSIF TG_TABLE_NAME='media_jobs' THEN blocked:=NEW.state IN('queued','running');ELSE blocked:=true;END IF;
 IF fenced IS NOT NULL AND blocked THEN RAISE EXCEPTION 'media account erased' USING ERRCODE='42501';END IF;RETURN NEW;END$$;
CREATE TRIGGER media_objects_gate BEFORE INSERT OR UPDATE ON media_objects FOR EACH ROW EXECUTE FUNCTION media_enforce_write_gate();
CREATE TRIGGER media_slots_gate BEFORE INSERT OR UPDATE ON media_upload_slots FOR EACH ROW EXECUTE FUNCTION media_enforce_write_gate();
CREATE TRIGGER media_grants_gate BEFORE INSERT OR UPDATE ON media_use_grants FOR EACH ROW EXECUTE FUNCTION media_enforce_write_gate();
CREATE TRIGGER media_jobs_gate BEFORE INSERT OR UPDATE ON media_jobs FOR EACH ROW EXECUTE FUNCTION media_enforce_write_gate();
CREATE TRIGGER media_commands_gate BEFORE INSERT OR UPDATE ON media_commands FOR EACH ROW EXECUTE FUNCTION media_enforce_write_gate();

ALTER TABLE media_objects ADD COLUMN last_source_checked_at timestamptz(3);
ALTER TABLE media_upload_slots ADD COLUMN input_deleted_at timestamptz(3), ADD COLUMN cleanup_checked_at timestamptz(3);
